let currentModule = '';

function openModal(tabId, modNameKey, icon) {
  const lang = currentLang;
  const t = modalLang[lang];
  const modName = T[lang][modNameKey] || modNameKey;
  document.getElementById('modalTitle').textContent = t.title;
  document.getElementById('modalTag').textContent = icon + ' ' + modName;
  currentModule = modName;
  document.getElementById('modalSub').textContent = t.sub;
  document.getElementById('labelCompany').textContent = t.labelCompany;
  document.getElementById('labelEmail').textContent = t.labelEmail;
  document.getElementById('inputCompany').placeholder = t.placeholderCompany;
  document.getElementById('inputEmail').placeholder = t.placeholderEmail;
  document.getElementById('submitBtnText').textContent = t.submitBtn;
  document.getElementById('modalNote').textContent = t.note;
  document.getElementById('successTitle').textContent = t.successTitle;
  document.getElementById('successSub').textContent = t.successSub;
  // Reset state
  document.getElementById('modalForm').style.display = '';
  document.getElementById('modalSuccess').style.display = 'none';
  document.getElementById('inputCompany').value = '';
  document.getElementById('inputEmail').value = '';
  document.getElementById('inputCompany').classList.remove('error');
  document.getElementById('inputEmail').classList.remove('error');
  document.getElementById('priceModal').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function closeModal() {
  document.getElementById('priceModal').classList.remove('open');
  document.body.style.overflow = '';
}

function handleModalOverlayClick(e) {
  if (e.target === document.getElementById('priceModal')) closeModal();
}

function isValidCorporateEmail(email) {
  const freeProviders = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com', 'mail.ru', 'yandex.com', 'protonmail.com'];
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!re.test(email)) return false;
  const domain = email.split('@')[1].toLowerCase();
  return !freeProviders.includes(domain);
}

async function submitPriceRequest() {
  const lang = currentLang;
  const t = modalLang[lang];
  const company = document.getElementById('inputCompany').value.trim();
  const email = document.getElementById('inputEmail').value.trim();
  let valid = true;

  document.getElementById('inputCompany').classList.remove('error');
  document.getElementById('inputEmail').classList.remove('error');

  if (!company) {
    document.getElementById('inputCompany').classList.add('error');
    valid = false;
  }
  if (!isValidCorporateEmail(email)) {
    document.getElementById('inputEmail').classList.add('error');
    valid = false;
  }
  if (!valid) return;

  const btn = document.getElementById('modalSubmitBtn');
  btn.disabled = true;
  document.getElementById('submitBtnText').textContent = t.sending;

  try {
    const serviceID = "service_4okz8hm";
    const templateID = "template_falwu3m";

    await emailjs.send(serviceID, templateID, {
      name: company,
      email: email,
      message: `Module: ${currentModule}\nCompany: ${company}\nEmail: ${email}`,
    });
  } catch (err) {
    console.error('EmailJS send failed:', err);
  }

  // Show success
  document.getElementById('modalForm').style.display = 'none';
  document.getElementById('modalSuccess').style.display = 'block';
  btn.disabled = false;
}

