function renderPills(lang) {
  for (const [tabId, data] of Object.entries(PILLS_DATA)) {
    const container = document.getElementById('pills-' + tabId);
    if (!container) continue;
    const items = data[lang] || data['en'];
    container.innerHTML = items.map(([icon, strong, bcls, btxt]) =>
      `<div class="value-pill">
        <div class="value-pill-icon">${icon}</div>
        <div class="value-pill-text"><strong>${strong}</strong></div>
        ${btxt ? `<span class="value-pill-badge ${bcls}">${btxt}</span>` : ''}
      </div>`
    ).join('');
  }
}

